require __DIR__.'/inc/smtp-mail.php';sm_admin();$err='';$ok='';if($_SERVER['REQUEST_METHOD']==='POST'){verify();try{$action=$_POST['action']??'';if($action==='tables'){db()->exec("CREATE TABLE IF NOT EXISTS v112_mail_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quote_id INT NOT NULL,recipient VARCHAR(190) NOT NULL,status VARCHAR(20) NOT NULL,actor_id INT NULL,detail VARCHAR(300) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_quote (quote_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$ok='Gönderim kayıtları tablosu hazır.';}elseif($action==='settings'){$old=sm_settings();$host=trim($_POST['host']??'');$port=(int)($_POST['port']??0);$security=$_POST['security']??'';$username=trim($_POST['username']??'');$from=trim($_POST['from']??'');$password=(string)($_POST['password']??'');if(!preg_match('/^[a-zA-Z0-9.-]{3,190}$/',$host)||!in_array($port,[465,587,2525],true)||!in_array($security,['ssl','starttls'],true)||!filter_var($username,FILTER_VALIDATE_EMAIL)||!filter_var($from,FILTER_VALIDATE_EMAIL))throw new Exception('SMTP bilgilerini kontrol edin.');if($password===''&&!isset($old['password']))throw new Exception('İlk kurulumda posta kutusu şifresi gereklidir.');if(strlen($password)>512)throw new Exception('Şifre çok uzun.');sm_save(['host'=>$host,'port'=>$port,'security'=>$security,'username'=>$username,'from'=>$from,'password'=>$password!==''?$password:$old['password']]);$ok='SMTP ayarları güvenli yapılandırma dosyasına kaydedildi.';}else throw new Exception('Geçersiz işlem.');}catch(Throwable $e){$err=$e->getMessage();}}
$c=sm_settings();require __DIR__.'/inc/layout.php';top('SMTP Ayarları');?><link rel="stylesheet" href="assets/v112-mail.css"><div class="v112-wrap"><div class="v112-head"><h1>Kurumsal SMTP Ayarları</h1><p>Teklif e-postalarını panelden gönderin. Şifreyi yalnızca bu yönetici ekranına girin; ZIP dosyasına eklemeyin.</p></div><?php if($err):?><p class="error"><?=h($err)?></p><?php endif;if($ok):?><p class="notice"><?=h($ok)?></p><?php endif;?><div class="v112-card"><h2>1. Gönderim geçmişini hazırla</h2><p>Mevcut verileri değiştirmeden yalnızca yeni kayıt tablosu oluşturur.</p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="tables"><button>Tabloyu Oluştur / Kontrol Et</button></form><p>Durum: <?=sm_ready()?'Hazır':'Kurulum bekliyor'?></p></div><div class="v112-card"><h2>2. SMTP bağlantısı</h2><p>Posta sağlayıcınızın verdiği sunucu adresini kullanın. 465/SSL veya 587/STARTTLS önerilir.</p><form method="post" autocomplete="off"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="settings"><div class="v112-grid"><label>SMTP Sunucusu<input name="host" required value="<?=h($c['host']??'')?>" placeholder="mail.ornekalanadi.com"></label><label>Port<select name="port"><option value="465" <?=($c['port']??465)==465?'selected':''?>>465</option><option value="587" <?=($c['port']??0)==587?'selected':''?>>587</option><option value="2525" <?=($c['port']??0)==2525?'selected':''?>>2525</option></select></label><label>Bağlantı Güvenliği<select name="security"><option value="ssl" <?=($c['security']??'ssl')==='ssl'?'selected':''?>>SSL/TLS</option><option value="starttls" <?=($c['security']??'')==='starttls'?'selected':''?>>STARTTLS</option></select></label><label>SMTP Kullanıcı Adı<input name="username" type="email" required value="<?=h($c['username']??'')?>"></label><label>Gönderici Adresi<input name="from" type="email" required value="<?=h($c['from']??'teklif@eksiogluloijstik.com')?>"></label><label>Posta Kutusu Şifresi<input name="password" type="password" autocomplete="new-password" placeholder="<?=isset($c['password'])?'Değiştirmeyecekseniz boş bırakın':'İlk kurulumda girin'?>"></label></div><button>SMTP Ayarlarını Kaydet</button></form></div><p><a class="btn secondary" href="v112-mail.php">Teklif Gönderim Ekranına Git</a></p></div><?php bottom();
